package tests

import (
	"testing"

	"github.com/ardoq/graphlake/query/sparql"
	"github.com/stretchr/testify/assert"
)

// ARD-33544: a variable bound inside an annotated triple pattern must be usable
// as a join key by the rest of the query. It was not. The planner's variable
// extraction only looked at the top-level subject/predicate/object, so a
// variable nested in <<( ... )>> was invisible; patterns joined only through one
// were judged to share nothing and evaluated independently, and the other side
// of the join ran unconstrained across the whole store.
//
// The numbers in these tests are the measured pre-fix results, so each one fails
// if the extraction stops descending into triple terms.

const ard33544Reifies = "<http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies>"

// ard33544Store holds one reified statement plus a label for each of its three
// terms and one unrelated subject — four labelled subjects in total, which is
// what an unconstrained pattern falls back to matching.
func ard33544Store(t *testing.T) *sparql.QueryEvaluator {
	t.Helper()
	return rdf12Setup(t, "urn:g",
		`WITH <urn:g> INSERT {
			<< <http://ex/source> <http://ex/reftype-A> <http://ex/target> ~ <http://ex/ref1> >> <http://ex/src> "doc" .
			<http://ex/reftype-A> <http://ex/label> "Type A" .
			<http://ex/source>    <http://ex/label> "Source" .
			<http://ex/target>    <http://ex/label> "Target" .
			<http://ex/unrelated> <http://ex/label> "Not this one" .
		}`)
}

func ard33544Rows(t *testing.T, ev *sparql.QueryEvaluator, query string) []sparql.Mapping {
	t.Helper()
	qc, err := sparql.ParseQuery(query)
	assert.NoError(t, err)
	iter, err := ev.EvaluateQuery(qc)
	assert.NoError(t, err)
	var out []sparql.Mapping
	for {
		m, ok := iter.Next()
		if !ok {
			return out
		}
		out = append(out, m)
	}
}

// assertIRI checks a binding is the expected IRI, reporting what it actually was
// — before the fix these came back as unrelated subjects, including the engine's
// internal urn:x-triple: reifier ids.
func assertIRI(t *testing.T, m sparql.Mapping, key, want, context string) {
	t.Helper()
	iri, ok := m[key].(*sparql.IRI)
