	store, storeErr := s.storeForRequest(c, storeName)
	if storeErr != nil {
		return s.respondStoreLookupFailed(c, storeName, storeErr)
	}
	branchName := c.QueryParam("branch")
	if branchName == "" {
		branchName = "main"
	}

	// Retrieve schema context if a schema graph is provided
	var schemaSummary *SchemaSummary
	if schemaGraph := c.QueryParam("schemaGraph"); schemaGraph != "" {
		var err error
		schemaSummary, err = s.loadSchemaSummary(c, storeName, branchName, schemaGraph)
		if err != nil {
			s.loggerForRequest(c).Error("Failed to load schema", "server.TalkHandler", err)
		}
	}

	sparqlQuery, err := s.LLM.GenerateSPARQL(c.Request().Context(), req.Question, schemaSummary)
	if err != nil {
		s.loggerForRequest(c).Error("Failed to generate SPARQL", "server.TalkHandler", err)
		return c.JSON(http.StatusInternalServerError, map[string]any{"error": err.Error()})
	}

	branch := store.GetBranch(branchName)
	if branch == nil && store.MultiNode {
		if err := store.ReloadBranchList(); err != nil {
			s.loggerForRequest(c).Error("Failed to reload branch list", "server.TalkHandler", err)
			return c.JSON(http.StatusInternalServerError, map[string]any{"error": err.Error(), "query": sparqlQuery})
		}
		branch = store.GetBranch(branchName)
	}
	if branch == nil {
		s.loggerForRequest(c).Error("Branch not found", "server.TalkHandler", errors.New("branch not found"))
		return c.JSON(http.StatusNotFound, map[string]any{"error": "branch not found", "query": sparqlQuery})
