// openReadOnlyTxn opens the transaction the request's snapshot selectors ask for,
// and nothing else. Its caller owns decorating it; keeping the two apart is what
// stops a new selector arriving with the decoration left off.
func (s *Server) openReadOnlyTxn(c echo.Context, branch *core.Branch) (*core.Transaction, error) {
	// A tag used to select the snapshot, and it used to take precedence over
	// both selectors below. Ignoring one now would quietly answer from the branch
	// head — the newest data instead of the historical view the caller asked for,
	// with nothing to indicate the substitution. Say so instead.
	if c.QueryParam("tag") != "" {
		return nil, fmt.Errorf("the tag selector has been removed: find the snapshot by searching its metadata on /stores/:store/snapshots, then read it with snapshot_id")
